package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact API67 source and metadata from four fresh Salesforce-admitted timing/scope cells.
func TestRunQueueableBatchTimingAdmitted(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeMatrixBatch67.cls"), "public class GladeMatrixBatch67 implements Database.Batchable<SObject> {\n private Boolean withRow;\n public GladeMatrixBatch67(Boolean requested){withRow=requested;}\n public Iterable<SObject> start(Database.BatchableContext context){\n  insert new Account(Name='owned-matrix-start',Description=String.valueOf(withRow));\n  if(withRow)return new List<SObject>{new Account(Name='scope')};\n  return new List<SObject>();\n }\n public void execute(Database.BatchableContext context,List<SObject> scope){\n  insert new Account(Name='owned-matrix-execute',Description=String.valueOf(scope.size()));\n }\n public void finish(Database.BatchableContext context){insert new Account(Name='owned-matrix-finish');}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeMatrixBatch67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeMatrixQueue67.cls"), "public class GladeMatrixQueue67 implements Queueable {\n private Boolean withRow;\n public GladeMatrixQueue67(Boolean requested){withRow=requested;}\n public void execute(QueueableContext context){\n  insert new Account(Name='owned-matrix-queue-enter');\n  Id childId=Database.executeBatch(new GladeMatrixBatch67(withRow),200);\n  insert new Account(Name='owned-matrix-queue-exit',Description=childId == null ? 'null-child' : 'has-child');\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeMatrixQueue67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeQBatchMatrixObserve67.cls"), "@IsTest private class GladeQBatchMatrixObserve67 {\n private static void snapshot(List<Object> phases,String phase){\n  List<String> jobs=new List<String>();\n  List<AsyncApexJob> observedJobs=[SELECT Id,ApexClass.Name,JobType,Status,ParentJobId,JobItemsProcessed,TotalJobItems,NumberOfErrors,ExtendedStatus,CompletedDate FROM AsyncApexJob];\n  Set<Id> parentIds=new Set<Id>();\n  for(AsyncApexJob job:observedJobs)if(job.ParentJobId!=null)parentIds.add(job.ParentJobId);\n  Map<Id,AsyncApexJob> parents=new Map<Id,AsyncApexJob>([SELECT Id,ApexClass.Name,JobType FROM AsyncApexJob WHERE Id IN :parentIds]);\n  for(AsyncApexJob job:observedJobs){\n   AsyncApexJob parent=parents.get(job.ParentJobId);\n   jobs.add(JSON.serialize(new List<Object>{job.ApexClass.Name,job.JobType,job.Status,job.ParentJobId!=null,parent==null ? null : parent.ApexClass.Name,parent==null ? null : parent.JobType,job.JobItemsProcessed,job.TotalJobItems,job.NumberOfErrors,job.ExtendedStatus,job.CompletedDate!=null}));\n  }\n  jobs.sort();List<String> effects=new List<String>();\n  for(Account row:[SELECT Name,Description FROM Account WHERE Name LIKE 'owned-matrix-%'])effects.add(JSON.serialize(new List<Object>{row.Name,row.Description}));\n  effects.sort();phases.add(new Map<String,Object>{'phase'=>phase,'jobs'=>jobs,'effects'=>effects});\n }\n private static void run(Boolean beforeStart,Boolean withRow){\n  List<Object> phases=new List<Object>();\n  if(beforeStart)System.enqueueJob(new GladeMatrixQueue67(withRow));\n  snapshot(phases,'beforeStart');\n  Test.startTest();\n  if(!beforeStart)System.enqueueJob(new GladeMatrixQueue67(withRow));\n  snapshot(phases,'insideStart');\n  Map<String,Object> stopped=new Map<String,Object>{'phase'=>'stop'};\n  try{Test.stopTest();stopped.put('returned',true);}catch(Exception e){stopped.put('returned',false);stopped.put('type',e.getTypeName());stopped.put('message',e.getMessage());}\n  phases.add(stopped);snapshot(phases,'afterStop');\n  String observation=JSON.serialize(new Map<String,Object>{'beforeStart'=>beforeStart,'withRow'=>withRow,'phases'=>phases});\n  System.assert(observation.length()<6500,'Owned queue-batch matrix observation bound');\n  verifyMatrix(phases,beforeStart,withRow);\n }\n @IsTest static void beforeStartEmptyBatch(){run(true,false);}\n @IsTest static void beforeStartOneRowBatch(){run(true,true);}\n @IsTest static void insideStartEmptyBatch(){run(false,false);}\n @IsTest static void insideStartOneRowBatch(){run(false,true);}\n\n private static void verifyMatrix(List<Object> phases,Boolean beforeStart,Boolean withRow){\n  String expectedJSON;\n  if(beforeStart && !withRow)expectedJSON='{\"phases\":[{\"effects\":[],\"jobs\":[\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,null,null,0,0,0,null,false]\"],\"phase\":\"beforeStart\"},{\"effects\":[],\"jobs\":[\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,null,null,0,0,0,null,false]\"],\"phase\":\"insideStart\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-matrix-finish\\\\\",null]\",\"[\\\\\"owned-matrix-queue-enter\\\\\",null]\",\"[\\\\\"owned-matrix-queue-exit\\\\\",\\\\\"has-child\\\\\"]\",\"[\\\\\"owned-matrix-start\\\\\",\\\\\"false\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeMatrixBatch67\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",false,null,null,0,0,0,null,true]\",\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Completed\\\\\",false,null,null,0,0,0,null,true]\"],\"phase\":\"afterStop\"}],\"withRow\":false,\"beforeStart\":true}';\n  else if(beforeStart && withRow)expectedJSON='{\"phases\":[{\"effects\":[],\"jobs\":[\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,null,null,0,0,0,null,false]\"],\"phase\":\"beforeStart\"},{\"effects\":[],\"jobs\":[\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,null,null,0,0,0,null,false]\"],\"phase\":\"insideStart\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-matrix-execute\\\\\",\\\\\"1\\\\\"]\",\"[\\\\\"owned-matrix-finish\\\\\",null]\",\"[\\\\\"owned-matrix-queue-enter\\\\\",null]\",\"[\\\\\"owned-matrix-queue-exit\\\\\",\\\\\"has-child\\\\\"]\",\"[\\\\\"owned-matrix-start\\\\\",\\\\\"true\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeMatrixBatch67\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",false,null,null,1,1,0,null,true]\",\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Completed\\\\\",false,null,null,0,0,0,null,true]\"],\"phase\":\"afterStop\"}],\"withRow\":true,\"beforeStart\":true}';\n  else if(!beforeStart && !withRow)expectedJSON='{\"phases\":[{\"effects\":[],\"jobs\":[],\"phase\":\"beforeStart\"},{\"effects\":[],\"jobs\":[\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,null,null,0,0,0,null,false]\"],\"phase\":\"insideStart\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-matrix-finish\\\\\",null]\",\"[\\\\\"owned-matrix-queue-enter\\\\\",null]\",\"[\\\\\"owned-matrix-queue-exit\\\\\",\\\\\"has-child\\\\\"]\",\"[\\\\\"owned-matrix-start\\\\\",\\\\\"false\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeMatrixBatch67\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",false,null,null,0,0,0,null,true]\",\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Completed\\\\\",false,null,null,0,0,0,null,true]\"],\"phase\":\"afterStop\"}],\"withRow\":false,\"beforeStart\":false}';\n  else if(!beforeStart && withRow)expectedJSON='{\"phases\":[{\"effects\":[],\"jobs\":[],\"phase\":\"beforeStart\"},{\"effects\":[],\"jobs\":[\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,null,null,0,0,0,null,false]\"],\"phase\":\"insideStart\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-matrix-execute\\\\\",\\\\\"1\\\\\"]\",\"[\\\\\"owned-matrix-finish\\\\\",null]\",\"[\\\\\"owned-matrix-queue-enter\\\\\",null]\",\"[\\\\\"owned-matrix-queue-exit\\\\\",\\\\\"has-child\\\\\"]\",\"[\\\\\"owned-matrix-start\\\\\",\\\\\"true\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeMatrixBatch67\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",false,null,null,1,1,0,null,true]\",\"[\\\\\"GladeMatrixQueue67\\\\\",\\\\\"Queueable\\\\\",\\\\\"Completed\\\\\",false,null,null,0,0,0,null,true]\"],\"phase\":\"afterStop\"}],\"withRow\":true,\"beforeStart\":false}';\n  else {System.assert(false,'Unknown matrix cell');return;}\n  Object actual=JSON.deserializeUntyped(JSON.serialize(new Map<String,Object>{'beforeStart'=>beforeStart,'withRow'=>withRow,'phases'=>phases}));\n  compareMatrix(JSON.deserializeUntyped(expectedJSON),actual,'matrix');\n }\n private static void compareMatrix(Object expected,Object actual,String path){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,'Expected map '+path);\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),'Complete keys '+path);\n   for(String key:want.keySet())compareMatrix(want.get(key),got.get(key),path+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,'Expected list '+path);\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),'Complete rows '+path);\n   for(Integer i=0;i<want.size();i++)compareMatrix(want[i],got[i],path+'['+i+']');\n  }else System.assertEquals(expected,actual,'Exact value '+path);\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeQBatchMatrixObserve67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Admitted queueable batch timing: %s", data)
	}
}
